Scripts.OnLoad:
-- Make the button movable by left-click dragging
this:SetMovable(true);
this:EnableMouse(true);
this:RegisterForDrag("LeftButton");
this:SetScript("OnDragStart", function()
  this:StartMoving();
end);
this:SetScript("OnDragStop", function()
  this:StopMovingOrSizing();
end);

Scripts.OnClick:
if (InstanceCounterMainFrame:IsShown()) then
  InstanceCounterMainFrame:Hide();
else
  InstanceCounterMainFrame:Show();
  InstanceCounter_UpdateDisplay();
end

Scripts.OnEnter:
GameTooltip:SetOwner(this, "ANCHOR_LEFT");
GameTooltip:SetText("Instance Counter");

-- Show last 5 instances with timestamps (skip RDF instances)
if #InstanceCounterDB.history > 0 then
  GameTooltip:AddLine("Last 5 instances:", 1, 1, 1);
  local displayedCount = 0
  local startIndex = math.max(1, #InstanceCounterDB.history - 4);
  for i = startIndex, #InstanceCounterDB.history do
    local entry = InstanceCounterDB.history[i];
    -- Skip RDF instances from tooltip
    if not IsRDFInstance(entry.name, entry.difficultyID) then
      local timeString = date("%H:%M", entry.time);
      GameTooltip:AddDoubleLine(
        string.format("%d. [%s]", displayedCount + 1, timeString),
        entry.name or "Unknown",
        1, 1, 1,
        1, 1, 1
      );
      displayedCount = displayedCount + 1
    end
  end
  if displayedCount == 0 then
    GameTooltip:AddLine("No instances to display (all RDF)", 0.6, 0.6, 0.6);
  end
else
  GameTooltip:AddLine("No instances recorded yet.", 0.6, 0.6, 0.6);
end

-- Add timer information
GameTooltip:AddLine(" ");
GameTooltip:AddLine("Timer Info:", 1, 0.8, 0);
if #InstanceCounterDB.history >= 5 then
  local fifthEntry = InstanceCounterDB.history[#InstanceCounterDB.history - 4]; -- 5th from last
  local entryTime = fifthEntry.time;
  local currentTime = time();
  local elapsed = currentTime - entryTime;
  local remaining = 3600 - elapsed; -- 1 hour in seconds

  if remaining > 0 then
    local hours = math.floor(remaining / 3600);
    local minutes = math.floor((remaining % 3600) / 60);
    local seconds = remaining % 60;
    GameTooltip:AddDoubleLine(
      "Next instance available in:",
      string.format("%02d:%02d:%02d", hours, minutes, seconds),
      1, 0.3, 0.3, -- Red color
      1, 0.3, 0.3
    );
  else
    GameTooltip:AddDoubleLine(
      "Status:",
      "You may enter a new instance",
      0.3, 1, 0.3, -- Green color
      0.3, 1, 0.3
    );
  end
else
  GameTooltip:AddLine("Need 5 instances to start timer", 0.6, 0.6, 0.6);
end

GameTooltip:Show();
